<style>
.player-dashboard{--muted:#97a9c2;--line:#223149;color:#edf4ff}.player-dashboard a{text-decoration:none}.player-welcome{position:relative;display:flex;justify-content:space-between;align-items:center;gap:30px;padding:36px 40px;background:radial-gradient(ellipse at 85% 25%,#23457b55,transparent 60%),linear-gradient(115deg,#14223b,#101a2c);border:1px solid #2b3c58;border-radius:20px;overflow:hidden}.player-eyebrow{font-size:11px;letter-spacing:2px;font-weight:750;color:#79c7ff}.player-welcome h1{font-size:clamp(26px,3vw,38px);letter-spacing:-1.2px;line-height:1.2;margin:14px 0}.player-welcome h1 span{color:#8bcaff}.player-welcome p{font-size:14px;color:var(--muted);margin:0 0 24px;max-width:390px;line-height:1.7}.player-primary,.player-secondary{display:inline-flex;align-items:center;justify-content:space-between;gap:28px;padding:13px 20px;border-radius:10px;background:#2d95ee;color:white;font-size:13px;font-weight:700;transition:background .2s}.player-primary:hover{background:#167bd0}.player-art{position:relative;width:270px;flex-shrink:0;text-align:center}.player-art svg{position:relative;width:240px;transform:rotate(-12deg);filter:drop-shadow(0 16px 25px #0005)}.art-orbit{position:absolute;width:240px;height:240px;top:-30px;left:15px;border:1px solid #5e9ee72b;border-radius:50%;box-shadow:0 0 0 28px #6090dd08,0 0 0 56px #6090dd05}.art-label{position:relative;display:block;font-size:9px;letter-spacing:2px;color:#95b0d3;margin-top:12px}.player-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0 30px}.player-stat{display:flex;align-items:center;gap:14px;padding:20px;background:#111d2f;border:1px solid var(--line);border-radius:13px}.stat-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;font-size:25px;background:#7a8cff12;color:#b4a3ff}.stat-icon.pink{color:#f09ec7;background:#ec83b112}.stat-icon.blue{color:#7cc5ff;background:#549aff12}.stat-icon.gold{color:#f3ca82;background:#ffc56812}.player-stat strong{display:block;font-size:24px;line-height:1.2}.player-stat div>span{font-size:11px;color:var(--muted)}.stat-arrow{margin-left:auto;color:#6c839f}.player-columns{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}.player-feed{min-width:0}.player-section{margin-bottom:28px}.player-section-heading{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:16px}.player-dashboard h2{font-size:18px;letter-spacing:-.4px;margin:0}.player-section-heading p{font-size:12px;color:var(--muted);margin:6px 0 0}.player-section-heading>a{font-size:12px;color:#85c7ff;white-space:nowrap}.player-empty{display:flex;align-items:center;gap:18px;padding:30px 24px;min-height:150px;background:#101b2b;border:1px dashed #2a3c56;border-radius:14px}.empty-symbol{display:grid;place-items:center;width:48px;height:48px;flex-shrink:0;background:#18283e;color:#7eabdc;border-radius:14px;font-size:27px}.player-empty h3{font-size:14px;margin:0 0 7px}.player-empty p{font-size:12px;color:var(--muted);margin:0;line-height:1.5}.player-empty>a{font-size:12px;color:#86c9ff;margin-left:auto;white-space:nowrap}.player-games{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.player-game{overflow:hidden;border-radius:12px;background:#142136;border:1px solid var(--line);transition:transform .2s}.player-game:hover{transform:translateY(-3px)}.player-game img{width:100%;aspect-ratio:4/3;object-fit:cover;display:block}.player-game>div{padding:12px}.player-game h3{font-size:13px;margin:0 0 8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.player-game span{font-size:10px;color:#85c7ff}.player-lottery{padding:24px;border:1px solid #504532;border-radius:15px;background:radial-gradient(ellipse at top right,#74552d35,transparent),#181f2b}.player-lottery .player-eyebrow{color:#dfbd80;letter-spacing:1.5px}.player-lottery h2{margin-top:15px;line-height:1.4}.player-lottery p{font-size:12px;line-height:1.6;color:var(--muted)}.lottery-summary{display:flex;gap:45px;margin:22px 0}.lottery-summary strong{display:block;font-size:26px}.lottery-summary span{font-size:11px;color:var(--muted)}.player-secondary{width:100%;background:#cfa968;color:#1c2330;box-sizing:border-box}.player-secondary:hover{background:#e1bc7a}.lottery-results{display:block;text-align:center;font-size:11px;color:#d6c099;margin-top:14px}.player-account{margin-top:18px;padding:22px;background:#111d2f;border:1px solid var(--line);border-radius:15px}.player-account h2{font-size:15px;margin-bottom:10px}.player-account>a{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid var(--line);font-size:12px}.player-account>a:last-child{border:0;padding-bottom:0}.player-account small{display:block;font-size:10px;color:var(--muted);margin-top:5px;line-height:1.5}.player-dashboard a:focus-visible{outline:2px solid #86c9ff;outline-offset:4px}@media(max-width:1050px){.player-stats{grid-template-columns:repeat(2,1fr)}.player-games{grid-template-columns:repeat(2,minmax(0,1fr))}.player-empty{flex-wrap:wrap}.player-empty>a{margin-left:66px}}@media(max-width:740px){.player-welcome{padding:28px 24px}.player-art{display:none}.player-columns{grid-template-columns:1fr}.player-sidebar{display:grid;grid-template-columns:1fr 1fr;gap:16px}.player-account{margin-top:0}.player-stats{gap:10px}.player-stat{padding:16px;gap:10px}.stat-arrow{display:none}}@media(max-width:480px){.player-sidebar{grid-template-columns:1fr}.player-welcome h1{font-size:28px}.player-stat{padding:14px 12px}.stat-icon{width:32px;height:32px;font-size:21px}.player-stat strong{font-size:21px}.player-section-heading p{max-width:220px;line-height:1.5}.player-empty{padding:24px 18px}.player-empty>a{margin-left:0}.player-empty>div{flex:1;min-width:150px}}
